def hasMatch(s: str, p: str) -> bool:
    star_index = p.index('*')
    prefix = p[:star_index]
    suffix = p[star_index + 1:]

    # Check all possible starting positions for the prefix
    for i in range(len(s) - len(prefix) - len(suffix) + 1):
        # Check if the current substring can match the prefix
        if s[i:i + len(prefix)] == prefix:
            # Check if the remaining part of s can match the suffix
            if s[i + len(prefix):].endswith(suffix):
                return True
    return False

