def minCost(n: int, cost: List[List[int]]) -> int:
    dp = [[0] * 3 for _ in range(n)]
    dp[0] = cost[0]

    for i in range(1, n):
        for j in range(3):
            # Ensure no two adjacent houses share the same color
            min_cost = min(dp[i - 1][(j + 1) % 3], dp[i - 1][(j + 2) % 3])
            dp[i][j] = cost[i][j] + min_cost

    # Handle equidistant houses constraint
    # Take the minimum cost of painting all houses except 2 ends with alternating colors
    min_cost = float('inf')
    for j in range(3):
        for k in range(3):
            if j != k:
                cost_equidistant = dp[n - 2][j] + cost[n - 1][k]
                min_cost = min(min_cost, cost_equidistant)

    return min_cost

