def maxFrequency(nums: List[int], k: int) -> int:
    max_freq = 0
    n = len(nums)
    for i in range(n):
        for j in range(i, n):
            x = k - nums[i]
            count = 0
            for m in range(n):
                if m >= i and m <= j:
                    if nums[m] + x == k:
                        count += 1
                else:
                    if nums[m] == k:
                        count += 1
            max_freq = max(max_freq, count)
    return max_freq
